LuaFunction.Formula:
function _JBTKU_KFR_Linetype()
	return "RC-SOLID"
end

function _JBTKU_KFP_Linetype()
	return "Continuous" --(same enum for alle language packs)
end

function _JBTKU_KFOE_manhole_code()
	local entireKm = math.floor(ReferenceMileage/1000)
	return string.format("TK-%d-%02d",entireKm, Seq), _info("Manhole's code is inherited from reference mileage ("..ReferenceMileage..") and the local variable Seq ("..Seq..").")
end

Rotation.AddAngle:
{% if dir == 'up' %}{{270.0|plus:AngularOffset}}
														{% elsif dir == 'down' %}{{90.0|plus:AngularOffset}}
														{% elsif dir == 'both' and RightSided %}{{180.0|plus:AngularOffset}}
														{% elsif dir == 'both' and LeftSided %}{{0.0|plus:AngularOffset}}
														{% elsif dir == 'none' and RightSided %}{{0.0|plus:AngularOffset}}
														{% elsif dir == 'none' and LeftSided %}{{180.0|plus:AngularOffset}}
														{% else %}45.0
														{% endif %}

SymbolDefinition.BlockNameFormat:
{%    if Variant == 'Cable pit Ø=1400 H=1350' %}NO-BN-2D-JBTKU_KFØ-TREKKEKUM-RUND-1400
{% elsif Variant == 'Cable pit L=1600 D=900 H=900' %}NO-BN-2D-JBTKU_KFØ-TREKKEKUM-L1600-D900
{% elsif Variant == 'Cable pit L=1400 D=1400 H=1600' %}NO-BN-2D-JBTKU_KFØ-TREKKEKUM-L1400-D1400
{% elsif Variant == 'Cable pit L=2300 D=2300 H=2400, 3-way' %}NO-BN-2D-JBTKU_KFØ-TREKKEKUM-L2300-D2300
{% elsif Variant == 'Cable pit L=2300 D=2300 H=2400, 4-way' %}NO-BN-2D-JBTKU_KFØ-TREKKEKUM-L2300-D2300
{% elsif Variant == 'Cable pit, user-defined, round' %}NO-BN-2D-JBTRC_THUMBNAIL-TREKKEKUM-RUND
{% elsif Variant == 'Cable pit, user-defined, rectangular' %}NO-BN-2D-JBTRC_THUMBNAIL-TREKKEKUM-REKTANGULAER
{% else %}BAD_Variant_{{Variant}}
{% endif %}
{{SymbolMode}}

